const NAS_BASE_PATH = '/home/node/n8n-files/projects';

const input = $input.first().json;
const projectId = input.query?.project_id || '';
const folderPath = input.query?.folder_path || '';

if (!projectId || !folderPath) {
  throw new Error('Geen project_id of folder_path opgegeven.');
}

if (folderPath.includes('..') || folderPath.startsWith('/')) {
  throw new Error('Ongeldig pad.');
}

const targetDir = `${NAS_BASE_PATH}/${projectId}/${folderPath}`;

return [{ json: { projectId, folderPath, targetDir } }];

const result = $input.first().json;
const stdout = (result.stdout || '').trim();
const setup = $('Setup').first().json;

try {
  const parsed = JSON.parse(stdout);
  return [{ json: { success: true, folder_path: setup.folderPath, ...parsed } }];
} catch (e) {
  return [{ json: { success: false, error: 'Kan bestanden niet lezen: ' + e.message } }];
}
